[Form]  
public class FMCompleteRental extends FormRun
{
    FormDataSource rentalDS;
    FMVehicle vehicle;
    FMRental rental;

}

public void run()
{        
    super();         

    if(rental != null)
    {
        FMRental_EndDate.dateTimeValue(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone()));
        FMRental_StartMileage.value(rental.StartMileage); 
        FMRental_EndMileage.value(rental.EndMileage); 
    }
}

public void init()
{
    //If this form was opened with a Rental as context then
    if(element.args() != null && element.args().record() != null) 
    {
        //Grab that Rental context
        rentalDS = FormDataUtil::getFormDataSource(element.args().record());

        if(element.args().record().TableId == tableNum(FMPickupAndReturnTable))
        {
            FMPickupAndReturnTable cacheRecord = element.args().record();
            select firstonly forupdate rental where rental.RentalId == cacheRecord.RentalId;
        }
        else if(element.args().record().TableId == tableNum(FMRental))
        {
            rental = element.args().record();
        }

        if(rental != null)
        {
            select firstonly forupdate vehicle where vehicle.RecId == rental.Vehicle;
        }

    }

    super();
}

public void clicked()
{
    FMCustomerComments dbComment;
    utcdatetime currentDate = DateTimeUtil::utcNow(); 

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStart("FleetManagement", "Complete a rental");

    if(rental != null && vehicle != null)
    {
        if(FMRental_EndMileage.value() == 0)
        {
            warning("Please update the vehicle's mileage!");
            return;
        }

        if(Comment.text() != "")
        {
            //Add a new comment for this customer
            dbComment.CustomerID = rental.Customer;
            dbComment.Timestamp = currentDate;
            dbComment.Comment = Comment.text();
            dbComment.insert();
        }

        // Return the vehicle and update the reservation status. Log Xpp Transaction discrete event
        Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStart("FleetManagement", "Return vehicle");

        ttsbegin;

        vehicle.Status = FMVehicleStatus::InService;
        vehicle.Mileage = FMRental_EndMileage.value(); 
        vehicle.update(); 

        rental.State = FMReservationState::Complete;
        rental.EndDate = DateTimeUtil::removeTimeZoneOffset(FMRental_EndDate.dateTimeValue(), DateTimeUtil::getUserPreferredTimeZone()); 
        rental.EndMileage = FMRental_EndMileage.value(); 
        rental.update(); 

        FMCreateNewServiceWorkflow::fmAddMaintenanceRecord(vehicle, rental);

        ttscommit;

        Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStop("FleetManagement", "Return vehicle");
        info('This vehicle has been successfully queued for service!');

        if(rentalDS.table() == tableNum(FMPickupAndReturnTable))
        {
            //Delete updated record from backing cache
            FMPickupAndReturnTable cacheRecord = element.args().record();
            cacheRecord.delete();
        }

        rentalDS.research(true);
    }

    super();

    Microsoft.Dynamics.Application.Instrumentation.FleetManagementEventSource::EventWriteXppTransactionStop("FleetManagement", "Complete a rental");
}
